values ('dialog_mystery_quiet_greet', NULL, 'npc_mystery_iren_saye', 'greet', '[{"id": "greet", "text": "We heard it. We haven''t explained it. Three resonant ribs surround a fourth rib wrapped in old cloth. A listening bench faces away from the visible crystals toward a drainage channel.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "Cloth touches the fourth rib at a vibration point.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Iren wants a witness willing to compare Arcanum measurements with Children of the Shard oral accounts without appropriating either or declaring the Shard conscious.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 121)
