values ('dialog_mystery_armistice_greet', NULL, 'npc_mystery_maela_orr', 'greet', '[{"id": "greet", "text": "A finding has a boundary. Write it down. New lock bolts hold an old stone cabinet shut. A scorched relief ledger sits beside an undamaged metal duplicate, both bearing the same modern custody mark.", "options": [{"text": "What did you notice here?", "next": "observation", "action": ""}, {"text": "Why ask an outsider?", "next": "motive", "action": ""}, {"text": "I will look around first.", "next": "exit", "action": "exit"}]}, {"id": "observation", "text": "The lock uses a current custody mark.", "options": [{"text": "Tell me more.", "next": "greet", "action": ""}, {"text": "I will examine it.", "next": "exit", "action": "exit"}]}, {"id": "motive", "text": "Maela holds a limited mandate to compare a recent neutral relief archive with scattered field copies. She needs a witness outside its Custodian and AMA sponsors because both have an interest in appearing blameless.", "options": [{"text": "What did you notice?", "next": "observation", "action": ""}, {"text": "I will think about it.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The evidence remains available when you return.", "options": []}]'::jsonb, 'dialog_tree_master.json', 124)
