insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_001', 'fq_conc_001', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You there. I''m Commander Lirien Vale, and I''ve been waiting for someone with actual field potential to walk through that gate. The Aethel Gardens used to be the crown jewel of Xylos — terraced groves fed by the Cradle''s overflow, bioluminescent at night, one of the few things that survived the Severance mostly intact. Now they''re choking with Forest Slimes, and every convoy we lose to the ooze is another crack in Concordium''s supply chain.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Slimes aren''t random, Operative. Before the Severance, this soil was saturated with clean aethel energy from the Cradle''s natural overflow. When the Siphon overloaded and the Shard shattered, that overflow became contaminated — every root, every organism that absorbed it twisted into something new. The Slimes are what the Gardens'' old microbiome became after three hundred years of Severance corruption. The Great Schism cost me half my garrison to Iron Hegemony defectors, so I''m running this outpost lean. These supply routes are the only uncontested corridor into Nexus Core. They fall, the whole Concordium operation gets squeezed. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The first dispatch is a perimeter report, not a victory speech. The Garden crews need a corridor they can cross twice. In Aethel Gardens, Kill FOREST_SLIME x3. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Confirm assignment: Garden Mandate: First Watch 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 127)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_002', 'fq_conc_002', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The corridor is clearer, but the outpost perimeter is now surrounded on three sides by Aethel Sproutlings — corrupted seedlings that haven''t seen clean sunlight since before the Schism. They''ve been pressing in from the northern grove since dawn, and two of my guards reported cuts through standard-issue armor plating. The perimeter must hold.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "This outpost was built to serve as the Gardens'' forward monitoring station — we track aethel output fluctuations and relay them to Nexus Core for calibration. If these Sproutlings breach the perimeter and reach the monitoring equipment, we lose visibility on the entire eastern corridor. After the Schism, when the Iron Hegemony faction broke away and took a third of our engineering staff, we lost the ability to run redundant systems. There is no backup monitoring station. This one is it. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The first dispatch is a perimeter report, not a victory speech. The Garden crews need a corridor they can cross twice. In Aethel Gardens, Kill FOREST_SLIME x3. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Confirm assignment: Garden Mandate: Broken Signal 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 128)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_003', 'fq_conc_003', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "We have a structural problem. The bio-conductive wiring running through the Gardens'' eastern grove — fifteen years of installation work, the same wiring that channels aethel energy from the Gardens into Nexus Core — is being eaten alive. Garden Mites have bored into the conduit walls and they''re feeding on the wiring''s energy conduction layer. If the eastern grove fails, we lose primary power routing to three Nexus sectors.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The bio-conductive wiring was an innovation of the Concordium''s founding engineers — the same generation who first successfully reactivated the Siphon after the Severance. It took fifteen years because the original Aethelgardian conduit infrastructure had been shattered along with everything else. These Mites evolved specifically to consume that wiring — which means they''ve been a problem since the conduits were first laid. We''ve been managing the infestation for years. This incursion is worse. I cannot write the report that explains we lost Nexus Core power because of insects. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The first dispatch is a perimeter report, not a victory speech. The Garden crews need a corridor they can cross twice. In Aethel Gardens, Kill AETHEL_SPROUTLING x3. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Confirm assignment: Garden Mandate: Ashes on the Route 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 129)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_004', 'fq_conc_004', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The aethel conduits in the eastern corridor are humming at the wrong frequency — lower, dragging, like something has changed their internal structure. Our engineering team found the cause: Feral Rootlings have grown through the conduit walls and they''re drinking raw aethel energy directly from the lines. They weren''t in any pre-Severance bestiary. They''re something the conduits themselves created.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The conduits were carved by the Concordium''s founders — people who rebuilt the Aethel Cradle from ruins and wept when it first activated. They ran the conduit lines through the Gardens'' root systems to take advantage of the organic conductivity. The Rootlings were probably ordinary plant life before they contacted raw aethel. Three hundred years of feeding on the conduit''s energy has warped them into something that exists only in this place, dependent on the infrastructure they''re destroying. If the conduit lines fail tonight, Nexus Core goes dark. The Arcanum will be on the doorstep before morning. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The first dispatch is a perimeter report, not a victory speech. The Garden crews need a corridor they can cross twice. In Aethel Gardens, Kill GARDEN_MITE x3. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Confirm assignment: Garden Mandate: Quiet Perimeter 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 130)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_005', 'fq_conc_005', 'npc_concordium_class_trainer', 'greeting', '[{"id": "greeting", "text": "Commander Vale''s field reports reached Nexus Core faster than you''d expect. I''m Instructor Kael — the Concordium''s master trainer, a veteran of the earliest post-Schism skirmishes when the Hegemony''s defection was still raw and every patrol felt like it could become a civil war. Vale says you have field potential worth shaping. The Concordium rebuilt the Aethel Cradle from ruins. It did not do that with generalists. Before you go further, you need to choose your path.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Concordium recognizes three combat philosophies forged in the crucible of post-Schism survival. The Shield holds the line and absorbs damage so others don''t have to — the Schism taught us that fortified ground is the difference between survival and collapse. The Blade moves fast and strikes before the enemy can adapt — because the Hegemony''s defection proved that waiting too long costs everything. The Conduit channels aethel energy as force, reading the battlefield and amplifying the team — because the Cradle''s power is not just for industry. Every Concordium operative makes this choice. The wrong answer will not be punished. But it will define every engagement you fight from this day forward. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Instructor Kael: The first dispatch is a perimeter report, not a victory speech. The Garden crews need a corridor they can cross twice. In Aethel Gardens, Kill FERAL_ROOTLING x3. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Confirm assignment: Garden Mandate: A Debt Repaid 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 131)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_006', 'fq_conc_006', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Welcome to the Broken Civil Quarter — what''s left of it. Before the Great Schism, this was the beating heart of unified Nexus, where the Concordium''s administrative and engineering divisions worked side by side in buildings that actually had intact roofs. The Schism tore this district apart as badly as it tore the faction apart. Concordium engineers have located a viable breach point into the main reclamation corridor. But Tunnel Crawlers have nested in it.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Civil Quarter''s architecture is layered history. The upper buildings were built post-Severance by the original unified Concordium — the same faction that rebuilt the Cradle. The lower infrastructure, the tunnel system, dates back to before the Severance, possibly Aethelgardian construction. Tunnel Crawlers evolved in those lower tunnels, isolated from whatever happened above for centuries. They''re not aggressive by nature — they''re territorial, which means the breach point we''ve identified is directly through their primary nesting territory. There is no alternative route. We stake the Concordium''s flag in this district, or we cede it to whatever faction moves faster. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The first dispatch is a perimeter report, not a victory speech. The Garden crews need a corridor they can cross twice. In Aethel Gardens, Kill MEADOW_RABID_HARE x3. Vale has learned to ask what the field changed, not only whether the order was obeyed.", "options": [{"text": "Confirm assignment: Garden Mandate: The Missing Patrol 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 132)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_007', 'fq_conc_007', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "We have a retrieval problem. The original unified Concordium buried supply caches throughout the Civil Quarter — medical supplies, engineering manuals, communication arrays — against the day the Schism might be reversed and the faction reunified. Scavengers have been looting them for years. Some of those engineering manuals were written by my mother.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The caches were designed to survive indefinitely, sealed against contamination, indexed against the original Concordium''s administrative database — a database that the Schism split into three fragments, each faction holding a piece. The Scavengers aren''t ideologically motivated; they sell to whoever pays. That means Hegemony buyers, Arcanum buyers, possibly even the Meridian Compact. Every manual they extract from those caches and sell to a rival faction is knowledge that was meant to rebuild Nexus, going instead to fragment it further. The scrap metal they collect is secondary. The information is what matters. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The sentries are back on the line, but nobody calls the route safe after one clean pass. In Aethel Gardens, Kill FOREST_STAGLING x3. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Confirm assignment: Garden Mandate: Measure of Resolve 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 133)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_008', 'fq_conc_008', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "I know it sounds absurd — the Concordium survived the Severance, the Schism, three rival factions, and now a rat threatens the advance. A Civil Rat Alpha has claimed the old archive building and bred a colony large enough to collapse the reclaimed sector''s food supply if the infestation spreads. The irony is not lost on me. But the archive building contains something more important than the rat''s pride.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "That building was a secondary administrative repository for the original unified Concordium — not the primary archive, but a significant one. Communications logs from the weeks before the Schism, engineering specifications for Cradle infrastructure that none of the three post-Schism factions have successfully reconstructed, personnel records from the founding generation. The Alpha has nested in the lower storage vaults. Its colony has been using the document storage containers as nesting material. Every week we wait, more of what''s inside becomes irretrievably compromised. The Concordium does not accept that outcome. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The sentries are back on the line, but nobody calls the route safe after one clean pass. In Aethel Gardens, Kill AETHEL_WISP x3. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Confirm assignment: Garden Mandate: A Narrow Passage 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 134)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_009', 'fq_conc_009', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Deep in the ruins, there is a Rusted Warden still patrolling. Automated guardian technology from before the Schism — programmed with the original unified Concordium''s authentication protocols. It doesn''t recognize our current insignia. It doesn''t recognize any of the Schism''s successor factions. It doesn''t recognize anything except the threat-assessment protocols written into it over a century ago. And we are, by its reckoning, unauthorized personnel.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Our engineering team tried to reprogram it. Twice. The first team was driven back before they could interface with the command core — the Warden''s automated response treated the reprogramming attempt as a hostile intrusion. The second team managed to reach the interface before a power surge fried their equipment. The Warden''s command protocols are hardwired to the original unified Concordium''s authentication system — a system that no longer exists. The people who wrote those protocols are dead. The faction that issued those credentials fragmented into three. The machine doesn''t know any of this. It just knows its orders haven''t changed. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The sentries are back on the line, but nobody calls the route safe after one clean pass. In Broken Civil Quarter, Kill FERAL_SCAVENGER x3. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Confirm assignment: Garden Mandate: Unclaimed Ground 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 135)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_010', 'fq_conc_010', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "There is a Slime King in the sewers beneath the Civil Quarter. The sewers that the Concordium''s founding engineers designed as emergency water routing for a city of four million people — the infrastructure that was supposed to guarantee Nexus''s survival through any crisis. It has been the throne room of a Slime King for approximately eighty years. Since shortly after the Schism, if the biological dating on the core samples is accurate.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Slime King is not the product of the Severance''s initial corruption. It grew here, in the dark, after the Schism fractured the faction that built this place. The founding engineers'' greatest infrastructure achievement became an abandoned space within a generation of its construction. The Severance''s contamination seeped into the neglected water system, and something coalesced in the absence of maintenance, of oversight, of care. This is what neglect looks like, given eighty years and a corrupted water supply. The Concordium''s failure to hold this district together created the conditions for this creature''s existence. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The sentries are back on the line, but nobody calls the route safe after one clean pass. In Broken Civil Quarter, Kill CIVIL_RAT_ALPHA x1. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Confirm assignment: Garden Mandate: Before the Next Dawn 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 136)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_011', 'fq_conc_011', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "You''ve earned the right to see it. The Aethel Cradle''s Outer Ring — the great machine the Concordium built around Xylos''s most powerful energy source. The original engineers wept when they first activated it. I wasn''t there, but I''ve read the field journals, and I believe that account completely. Now the Outer Ring is contested ground, and every faction wants what it contains. I need you to scout it and make sure the Concordium holds the advantage.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Outer Ring was the Concordium''s greatest engineering achievement after the Cradle reactivation itself — a network of energy capture platforms encircling the Siphon''s primary output zone. Before the Great Schism, it supplied Nexus Core with enough aethel-derived power to run every system in the city indefinitely. The Schism disrupted the maintenance rotation, and now three factions fight over control of platforms that none of us has the full engineering staff to run properly. The void fragments you''ll find in the flux rift sites are debris from reality-thin zones where the Cradle''s energy output causes spatial instability. We use them as calibration data. They tell us how close to the edge the Outer Ring is operating. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The sentries are back on the line, but nobody calls the route safe after one clean pass. In Broken Civil Quarter, Kill BROKEN_SENTINEL x4. Valen records every open path because he has watched small omissions close them again.", "options": [{"text": "Confirm assignment: Garden Mandate: Witness at the Ridge 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 137)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_012', 'fq_conc_012', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Cradle Anomaly Wolves have been sighted near the flux rifts in the Outer Ring''s western sector. These aren''t standard predators — they''re what happens when a species spends generations in proximity to a malfunctioning aethel source. Their howls are operating on the same frequency band as our harmonic resonators. Every time a pack vocalizes near the resonators, the calibration drifts. Unchecked drift leads to cascade failure. The Concordium nearly lost the Cradle once. I refuse to let it happen again.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The resonators are what maintain stable energy output from the Outer Ring — they''re the mechanism that prevents the Cradle''s power from spiking into an uncontrolled surge the way it did during the Great Severance. The Aethelgardians didn''t have resonator technology when they activated the Siphon. That''s why the Shard shattered. We rebuilt the Siphon and added the resonator network specifically because we understood what went wrong. If the Anomaly Wolves'' vocalizations interfere with that network and cause a calibration failure, we recreate the conditions of the Severance. The entire Outer Ring''s operation is at risk from creatures that are themselves a product of the Severance''s original damage. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The next report links the local threat to a wider failure in the old settlement grid. In Cradle Outer Ring, Kill CRADLE_ANOMALY_WOLF x4. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Confirm assignment: Garden Mandate: Supply Line 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 138)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_013', 'fq_conc_013', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Cradle Anomaly Beastlings have nested in the maintenance shafts of the Outer Ring''s stabilizer array. Smaller than the Wolves, faster, and they''ve compromised the physical access routes our engineering teams use to maintain the stabilizers. Two maintenance rotations have been turned back already. If the array goes offline, the Arcanum Seekers will be on our doorstep before the stabilizers finish cooling.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The stabilizer array is what prevents the Outer Ring''s energy output from becoming unstable during peak load cycles. Think of it as the Cradle''s immune system — it detects imbalances and corrects them automatically, without human intervention. The Beastlings are probably the same species as the Anomaly Wolves at a juvenile life stage — the biological team isn''t certain, but their behavioral patterns suggest it. What they share is origin: creatures shaped by sustained aethel radiation, adapted to environments that should be lethal. They''re thriving in the maintenance shafts because the background radiation there would kill a standard organism in hours. It''s not killing them. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The next report links the local threat to a wider failure in the old settlement grid. In Cradle Outer Ring, Kill CRADLE_ANOMALY_WOLF x4. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Confirm assignment: Garden Mandate: The Last Warning 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 139)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_014', 'fq_conc_014', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Cradle Fragment Beasts are carrying unstable aethel cores inside their bodies — literal shards of the original Aethel Shard, still radiating energy, embedded in living hosts. The Arcanum Seekers want them captured for study. The Children of the Shard want them worshipped. The Concordium wants them contained before they detonate near the Outer Ring''s flux regulators and cause a cascade failure.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The prevailing theory from our biology division: in the immediate aftermath of the Severance, when the Shard shattered, the fragment scatter pattern spread across several hundred kilometers. Small organisms in the high-contamination zones ingested fragment material before the biological hazard was understood. Three centuries of biological integration have fused the fragment material with the host organism''s metabolic system. The cores are still energetically active — that''s why the Beasts are dangerous, and why they''re drawn to the Outer Ring. The Cradle''s energy output resonates with the embedded fragments. We believe they''re trying to return the shards to the source. They cannot be allowed to do that. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The next report links the local threat to a wider failure in the old settlement grid. In Cradle Outer Ring, Kill CRADLE_ANOMALY_BEASTLING x4. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Confirm assignment: Garden Mandate: A Question of Trust 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 140)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_015', 'fq_conc_015', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Sector Seven has been silent for three hours. The Resonance Bats swarming the communication arrays on the Outer Ring''s southern platform have effectively jammed our entire coordination network for that sector. These creatures evolved using the Cradle''s own harmonic emissions as echolocation — when they pulse near the arrays, their biological signal is indistinguishable from system noise. I check the comms every thirty seconds. Nothing comes back.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The communication arrays are how the Concordium coordinates Outer Ring defense. Without them, every patrol sector operates independently, without intelligence sharing, without support coordination. Three hours of silence means three hours where a Hegemony incursion, an Arcanum infiltration, or a void breach could happen in Sector Seven and we wouldn''t know until a patrol stumbled into it. The Resonance Bats are not strategically motivated — they''re drawn to the array''s harmonic output because it matches their echolocation frequency. But the effect is operationally equivalent to deliberate jamming. The Resonance Golems guarding their nest are amplifying the interference. Both have to go. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The next report links the local threat to a wider failure in the old settlement grid. In Cradle Outer Ring, Kill CRADLE_FRAGMENT_BEAST x4. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Confirm assignment: Garden Mandate: Outer Ring Report 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 141)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_016', 'fq_conc_016', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "Three scouts went dark in the eastern sector three days ago. I''ve entered their names in the operational record. Now I need you to enter the sector and recover the data they were carrying — void fragment calibration samples and an intelligence packet on Hegemony troop movements near the Cradle''s loading docks. The data doesn''t expire. The scouts are gone. The mission continues.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The void fragment calibration samples they carried are irreplaceable in the short term — we pulled them from a specific flux rift that has since destabilized and is no longer safely accessible. The intelligence packet was compiled over six weeks by a surveillance team I cannot replace either. The Cradle Anomaly Wolves are responsible for the scouts'' situation — we found trace evidence consistent with pack behavior in the vicinity of their last reported position. I report this precisely, without additional comment, because that is what the operational record requires of me. And because the mission requires clarity, not grief. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: The next report links the local threat to a wider failure in the old settlement grid. In Cradle Outer Ring, Kill CRADLE_WARDEN x4. A scout''s observations are now part of the operational record, not a footnote.", "options": [{"text": "Confirm assignment: Garden Mandate: No Safe Shortcut 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 142)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_017', 'fq_conc_017', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "A void breach has opened in the Outer Ring''s north platform. Not a flux rift — a full breach, where the boundary between normal space and whatever geometry feeds the void has thinned to near-zero. Fragment Beasts are pouring through and growing stronger with each surge. Concordium engineers believe the breach appeared the same week the Iron Hegemony began unauthorized excavation near the Cradle''s base. That may be coincidence. It may not.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Hegemony''s excavation team has been drilling into the Cradle''s outer geological substrate — the deep rock layer where the original Aethelgardian construction anchored the Siphon''s foundation. If they''ve penetrated the Siphon''s root structure, they may have destabilized the same containment geometry that the Aethelgardians built to prevent void ingress. This is the mechanism the Concordium believes triggered the original Severance — not the Siphon overload itself, but a void geometry failure that the overload then exploited. The Hegemony either doesn''t know what they''ve done, or they don''t care. Neither possibility is acceptable. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: A cleared site still has to support the people sent to occupy it. In Cradle Outer Ring, Kill CRADLE_WARDEN x4. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Confirm assignment: Garden Mandate: Aethel Aftershock 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 143)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_018', 'fq_conc_018', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Resonance Golems in the deep Outer Ring have established a concentration point — not a random nest, a deliberate defensive arrangement. Concordium historians believe these constructs are the Aethel Cradle''s original defense systems, built by the same Aethelgardian architects who first activated the Siphon. They''re still following protocols from before recorded history. And their harmonic pulses are rewriting our communication protocols with something older and stranger.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Golem emissions are what our signal analysis team is describing as ''pre-language'' — structured harmonic patterns that predate anything in the Concordium''s linguistic database. The same patterns appear in fragments of Aethelgardian inscription recovered from the Cradle''s deeper chambers, but no one has been able to fully translate them. The Golems are broadcasting these patterns continuously, and our communication infrastructure is beginning to incorporate them into its error-correction responses. In six weeks, if this continues, our comm arrays will be outputting Aethelgardian protocols instead of Concordium standard. The Concordium does not discard knowledge, but neither does it allow unknown protocols to overwrite operational infrastructure. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: A cleared site still has to support the people sent to occupy it. In Cradle Outer Ring, Kill CRADLE_WARDEN x4. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Confirm assignment: Garden Mandate: The Unquiet Machine 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 144)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_019', 'fq_conc_019', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Resonance Echo has materialized. This is beyond the Bats and the Golems — this is a concentrated echo of the Cradle''s original harmonic signature, coalesced into something that our instruments cannot categorize. The Arcanum Seekers would call it a miracle. The Children of the Shard would call it a god-fragment. I call it a threat to Concordium communication infrastructure that is currently rewriting Sector Nine''s relay protocols in real time.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The best working theory from our research division: the Outer Ring''s deep electromagnetic structure stores harmonic data the way biological tissue stores memory — passively, impressionistically, over centuries. What we''re seeing is that stored data achieving coherent form, a self-organizing energy entity built from the Cradle''s accumulated operational history. It is, in the most literal sense, a memory of the Aethel Cradle itself — before the Schism, before the Severance, possibly before human contact with the Siphon. Whatever it''s trying to do, it is operating on a timeline and according to goals we cannot parse. The Concordium cannot allow unknown entities to operate autonomously within Cradle infrastructure. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: A cleared site still has to support the people sent to occupy it. In Cradle Outer Ring, Kill CRADLE_WARDEN x4. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Confirm assignment: Garden Mandate: Terms of Passage 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 145)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_020', 'fq_conc_020', 'npc_concordium_officer', 'greeting', '[{"id": "greeting", "text": "The Outer Ring is not fully secured — it never will be, not while three factions and something older than all of them press against the Concordium''s borders. But we hold more of it today than we did a season ago, and that is because of what you''ve done here. This final sweep is also a test. The Concordium is evaluating you for Advanced assignment. The Cradle''s inner platforms await, and they will demand everything you have.", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Inner Cradle Exclusion Zone, the Cradle Expanse, the contested zones where all factions have active operations — these are not the Gardens, Operative. The threats there are not Slimes and Sproutlings. They''re creatures that have adapted to direct Shard energy proximity, Aethelgardian defense constructs that have been operating for centuries without human oversight, void-adjacent entities that don''t have biological analogs in any known database. You will need every skill you''ve developed in the Gardens and the Civil Quarter and the Outer Ring. This final sweep will tell us if you''re ready. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Officer Valen: A cleared site still has to support the people sent to occupy it. In Cradle Outer Ring, Kill CRADLE_WARDEN x4. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Confirm assignment: Garden Mandate: Report to Command 01", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 146)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_021', 'fq_conc_021', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Deep Incursion — Push deeper into the Inner Cradle Exclusion", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: A cleared site still has to support the people sent to occupy it. In Cradle Outer Ring, Kill CRADLE_WARDEN x5. Vael counts tools, water, and names; the last column is the one he rereads.", "options": [{"text": "Confirm assignment: Garden Mandate: First Watch 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 147)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_022', 'fq_conc_022', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Inner Cradle Mutants exposed to raw aethel show extreme aggression", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. Hale wants a clean containment result. Vale asks what the result costs after the report is filed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The response is becoming a routine, and routine is where an unchecked assumption hides. In Cradle Outer Ring, Kill CRADLE_WARDEN x5. Hale wants a clean containment result. Vale asks what the result costs after the report is filed.", "options": [{"text": "Confirm assignment: Broken Charter: Broken Signal 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 148)
