values ('dialog_fq_conc_024', 'fq_conc_024', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Sentinel Protocol — Cradle Sentinels guard the ancient Cradle gates", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Hale wants a clean containment result. Vale asks what the result costs after the report is filed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The response is becoming a routine, and routine is where an unchecked assumption hides. In Cradle Outer Ring, Kill CRADLE_WARDEN x5. Hale wants a clean containment result. Vale asks what the result costs after the report is filed.", "options": [{"text": "Confirm assignment: Broken Charter: Quiet Perimeter 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 150)
