values ('dialog_fq_conc_025', 'fq_conc_025', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. A Cradle Void Stalker has been hunting Concordium operatives in the Exclusion", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. Hale wants a clean containment result. Vale asks what the result costs after the report is filed.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The response is becoming a routine, and routine is where an unchecked assumption hides. In Cradle Outer Ring, Kill CRADLE_WARDEN x5. Hale wants a clean containment result. Vale asks what the result costs after the report is filed.", "options": [{"text": "Confirm assignment: Broken Charter: A Debt Repaid 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 151)
