values ('dialog_fq_conc_029', 'fq_conc_029', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. Aethel Behemoths roam the Expanse", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: An old marker places this disturbance beside infrastructure built before Nexus had a name. In Inner Cradle Exclusion, Kill CRADLE_SENTINEL x5. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Confirm assignment: Broken Charter: Unclaimed Ground 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 155)
