values ('dialog_fq_conc_030', 'fq_conc_030', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. You have reached the Advanced threshold", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: An old marker places this disturbance beside infrastructure built before Nexus had a name. In Inner Cradle Exclusion, Kill CRADLE_PURIFIER x5. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Confirm assignment: Broken Charter: Before the Next Dawn 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 156)
