values ('dialog_fq_conc_031', 'fq_conc_031', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Concordium high command summons you to the Orbital Sentinel Command", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: An old marker places this disturbance beside infrastructure built before Nexus had a name. In Inner Cradle Exclusion, Kill CRADLE_PURIFIER x6. Rian trusts a footprint more than a faction''s version of the map.", "options": [{"text": "Confirm assignment: Broken Charter: Witness at the Ridge 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 157)
