insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_032', 'fq_conc_032', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. Aethel Iron Carapaces threaten orbital supply lanes", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen. The Guard Captain calls that adaptation. The workers call it losing half a night''s sleep.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Local crews have started changing their shifts around the hazard. In Inner Cradle Exclusion, Kill ARCANE_RIFT_BEAST x6. The Guard Captain calls that adaptation. The workers call it losing half a night''s sleep.", "options": [{"text": "Confirm assignment: Broken Charter: Supply Line 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 158)
