values ('dialog_fq_conc_035', 'fq_conc_035', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Aethel Abyssal Reavers have emerged", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. The Guard Captain calls that adaptation. The workers call it losing half a night''s sleep.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Local crews have started changing their shifts around the hazard. In Inner Cradle Exclusion, Kill ARCANE_RIFT_BEAST x6. The Guard Captain calls that adaptation. The workers call it losing half a night''s sleep.", "options": [{"text": "Confirm assignment: Broken Charter: Outer Ring Report 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 161)
