values ('dialog_fq_conc_038', 'fq_conc_038', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. Enemy infiltrators use orbital debris as cover", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Valen will certify the route; he will not certify a theory.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The evidence points inward, toward systems no present faction fully understands. In Inner Cradle Exclusion, Kill ARCANE_RIFT_BEAST x6. Valen will certify the route; he will not certify a theory.", "options": [{"text": "Confirm assignment: Broken Charter: The Unquiet Machine 02", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 164)
