values ('dialog_fq_conc_041', 'fq_conc_041', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. You descend into the Void Echo Chasm", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. Valen will certify the route; he will not certify a theory.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The evidence points inward, toward systems no present faction fully understands. In Inner Cradle Exclusion, Kill ARCANE_RIFT_BEAST x7. Valen will certify the route; he will not certify a theory.", "options": [{"text": "Confirm assignment: Broken Charter: First Watch 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 167)
