values ('dialog_fq_conc_042', 'fq_conc_042', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Void Reavers", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Vale is willing to carry uncertainty into the briefing. She will not let anyone disguise it as proof.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The field pattern repeats, but the surviving records do not agree on why. In Cradle Expanse, Kill AETHEL_VOID_CHANNELER x7. Vale is willing to carry uncertainty into the briefing. She will not let anyone disguise it as proof.", "options": [{"text": "Confirm assignment: Cradle Authority: Broken Signal 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 168)
