values ('dialog_fq_conc_047', 'fq_conc_047', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. A Gigantic Jotunn guards an ancient gate within the chasm", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. For the people who live here, a stable door matters more than a grand claim about the Cradle.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: One more secured sector gives the displaced crews somewhere to return to. In Cradle Expanse, Kill AETHEL_ABYSSAL_REAVER x7. For the people who live here, a stable door matters more than a grand claim about the Cradle.", "options": [{"text": "Confirm assignment: Cradle Authority: Measure of Resolve 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 173)
