values ('dialog_fq_conc_050', 'fq_conc_050', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The Ashen Drake rules the Shattered Heart", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen. For the people who live here, a stable door matters more than a grand claim about the Cradle.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: One more secured sector gives the displaced crews somewhere to return to. In Cradle Expanse, Kill AETHEL_ABYSSAL_REAVER x7. For the people who live here, a stable door matters more than a grand claim about the Cradle.", "options": [{"text": "Confirm assignment: Cradle Authority: Before the Next Dawn 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 176)
