values ('dialog_fq_conc_052', 'fq_conc_052', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Void Dominance — With the Soul Fragmenter destroyed, Concordium initiates Operation Void Dom...", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Vael knows every delayed crate has a person waiting at the other end of the manifest.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The operation now affects who can move supplies through the district. In Aethel Storm Ridge, Kill VOID_STALKER x8. Vael knows every delayed crate has a person waiting at the other end of the manifest.", "options": [{"text": "Confirm assignment: Cradle Authority: Supply Line 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 178)
