values ('dialog_fq_conc_057', 'fq_conc_057', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. Crystal Tyrants have organized into a hunting pack in the Heart", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. The record says what was measured. It does not say the Siphon caused this event.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: A recovered trace suggests the disturbance is connected to damaged Aethel infrastructure. In Aethel Storm Ridge, Kill CHRONO_WRAITH x8. The record says what was measured. It does not say the Siphon caused this event.", "options": [{"text": "Confirm assignment: Cradle Authority: Aethel Aftershock 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 183)
