values ('dialog_fq_conc_059', 'fq_conc_059', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Soul Fragmenters have multiplied throughout the chasm", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. The record says what was measured. It does not say the Siphon caused this event.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: A recovered trace suggests the disturbance is connected to damaged Aethel infrastructure. In Void Echo Chasm, Kill GIGANTIC_JOTUNN x1. The record says what was measured. It does not say the Siphon caused this event.", "options": [{"text": "Confirm assignment: Cradle Authority: Terms of Passage 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 185)
