values ('dialog_fq_conc_060', 'fq_conc_060', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. THE FINAL VOID TRIAL", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. The record says what was measured. It does not say the Siphon caused this event.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: A recovered trace suggests the disturbance is connected to damaged Aethel infrastructure. In Void Echo Chasm, Kill GIGANTIC_JOTUNN x1. The record says what was measured. It does not say the Siphon caused this event.", "options": [{"text": "Confirm assignment: Cradle Authority: Report to Command 03", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 186)
