insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_062', 'fq_conc_062', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Aethel Iron Carapaces swarm the faultline, drawn by tectonic energy", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Hale prefers a sealed perimeter; Vale knows a sealed perimeter can become a political border.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Rival claims are beginning to follow the same route as the field reports. In Titan Graveyard, Kill CRYSTAL_TYRANT x1. Hale prefers a sealed perimeter; Vale knows a sealed perimeter can become a political border.", "options": [{"text": "Confirm assignment: Severance Inquiry: Broken Signal 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 188)
