values ('dialog_fq_conc_063', 'fq_conc_063', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. Crystal Tyrants are exploiting the unstable terrain", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen. Hale prefers a sealed perimeter; Vale knows a sealed perimeter can become a political border.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Rival claims are beginning to follow the same route as the field reports. In Titan Graveyard, Kill CRYSTAL_TYRANT x1. Hale prefers a sealed perimeter; Vale knows a sealed perimeter can become a political border.", "options": [{"text": "Confirm assignment: Severance Inquiry: Ashes on the Route 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 189)
