values ('dialog_fq_conc_065', 'fq_conc_065', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Siphon Approach — The Aethel Siphon Core", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Hale prefers a sealed perimeter; Vale knows a sealed perimeter can become a political border.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Rival claims are beginning to follow the same route as the field reports. In Shattered Heart, Kill DRAKE_MINION x9. Hale prefers a sealed perimeter; Vale knows a sealed perimeter can become a political border.", "options": [{"text": "Confirm assignment: Severance Inquiry: A Debt Repaid 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 191)
