values ('dialog_fq_conc_067', 'fq_conc_067', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "You''re on time. Corrupted Behemoths are assaulting the Siphon Core''s primary conduits", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen. Rian marks what she can see and leaves the missing years blank.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The old civil quarter offers evidence, but not a single account of its past. In Shattered Heart, Kill DRAKE_MINION x9. Rian marks what she can see and leaves the missing years blank.", "options": [{"text": "Confirm assignment: Severance Inquiry: Measure of Resolve 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 193)
