values ('dialog_fq_conc_072', 'fq_conc_072', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Forge Guardians — The Forge has ancient automated defenses", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. The captain has stopped promising that a route will be quiet. Now he promises to be there.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The crew can hold the next position only if the approach stays usable. In Aethel Siphon Core, Kill CRYSTAL_TYRANT x1. The captain has stopped promising that a route will be quiet. Now he promises to be there.", "options": [{"text": "Confirm assignment: Severance Inquiry: Supply Line 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 198)
