values ('dialog_fq_conc_073', 'fq_conc_073', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Behemoth Foundry — Corrupted Behemoths have been drawn to the Forge''s energy signature", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. The captain has stopped promising that a route will be quiet. Now he promises to be there.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The crew can hold the next position only if the approach stays usable. In Aethel Siphon Core, Kill CRYSTAL_TYRANT x1. The captain has stopped promising that a route will be quiet. Now he promises to be there.", "options": [{"text": "Confirm assignment: Severance Inquiry: The Last Warning 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 199)
