values ('dialog_fq_conc_076', 'fq_conc_076', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. The Prima Materia War has begun", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. The captain has stopped promising that a route will be quiet. Now he promises to be there.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The crew can hold the next position only if the approach stays usable. In Eternal Gate, Kill GRAVITY_TITAN x1. The captain has stopped promising that a route will be quiet. Now he promises to be there.", "options": [{"text": "Confirm assignment: Severance Inquiry: No Safe Shortcut 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 202)
