values ('dialog_fq_conc_079', 'fq_conc_079', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Sovereign Claim — With the Forge secured, Concordium''s position is unassailable", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Nobody gets to call a disputed reading a warning from the Shard.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Aethel readings rise near the Cradle, though the instruments disagree on the scale. In Eternal Gate, Kill ASHEN_DRAKE x1. Nobody gets to call a disputed reading a warning from the Shard.", "options": [{"text": "Confirm assignment: Severance Inquiry: Terms of Passage 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 205)
