values ('dialog_fq_conc_080', 'fq_conc_080', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. You have defeated both Titan and Harbinger in a single campaign", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Nobody gets to call a disputed reading a warning from the Shard.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: Aethel readings rise near the Cradle, though the instruments disagree on the scale. In Eternal Gate, Kill ASHEN_DRAKE x1. Nobody gets to call a disputed reading a warning from the Shard.", "options": [{"text": "Confirm assignment: Severance Inquiry: Report to Command 04", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 206)
