values ('dialog_fq_conc_082', 'fq_conc_082', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. City Guardians — The Aethelgardian City is protected by ancient energy constructs", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Vale asked for the witness to be named. It cost her an hour with the review board.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The briefing includes a civilian report that was absent from yesterday''s official summary. In Eternal Gate, Kill ASHEN_DRAKE x1. Vale asked for the witness to be named. It cost her an hour with the review board.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Broken Signal 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 208)
