values ('dialog_fq_conc_087', 'fq_conc_087', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. All three Apex entities", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. An old record can be useful without being honest.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The next archive fragment may clarify the timeline, but its provenance is uncertain. In Eternal Gate, Kill ABYSS_HARBINGER x1. An old record can be useful without being honest.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Measure of Resolve 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 213)
