values ('dialog_fq_conc_092', 'fq_conc_092', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "At ease, Operative. Abyssal End — The Abyss is collapsing", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "We are not the strongest or richest faction. But we alone believe civilization is worth the cost. Prove that belief isn''t naive. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The line is holding through cooperation between crews that do not share a flag. In Eternal Gate, Kill ABYSS_HARBINGER x1. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Supply Line 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 218)
