values ('dialog_fq_conc_093', 'fq_conc_093', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. Crystal Tyrants have made their final stand in the Shattered Heart", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Cradle''s infrastructure is fragile. One functioning city, a thousand problems. We fix the cracks before they widen. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The line is holding through cooperation between crews that do not share a flag. In Eternal Gate, Kill ABYSS_HARBINGER x1. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: The Last Warning 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 219)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_094', 'fq_conc_094', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. The Prima Materia Forge must be completely purified of all void corruption", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The line is holding through cooperation between crews that do not share a flag. In Eternal Gate, Kill ABYSS_HARBINGER x1. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: A Question of Trust 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 220)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_095', 'fq_conc_095', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "Report to me, Operative. The Cradle Expanse is now officially Concordium sovereign territory", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "You earned your position through action, not politics. The Concordium remembers who showed up when walls were crumbling. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The line is holding through cooperation between crews that do not share a flag. In Eternal Gate, Kill ABYSS_HARBINGER x1. Valen dislikes the unofficial arrangement. He dislikes losing people more.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Outer Ring Report 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 221)
