insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_conc_100', 'fq_conc_100', 'npc_commander_vale', 'greeting', '[{"id": "greeting", "text": "The Concordium needs you. You have done the impossible", "options": [{"text": "What changed since the last report?", "next": "lore", "action": ""}, {"text": "I''ll take the assignment.", "next": "accept", "action": ""}, {"text": "Not yet.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Severance shattered our ability to maintain order. Every day we don''t act, another sector falls to chaos. This mission is how we hold the line. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Put me on the line.", "next": "accept", "action": ""}, {"text": "Back to the report.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Commander Lirien Vale: The Outer Ring remains contested; securing it is a continuing responsibility, not a finished map. In Eternal Gate, Kill ABYSS_HARBINGER x1. Vale will report the limits of Concordium control as clearly as its gains.", "options": [{"text": "Confirm assignment: Stewardship of the Siphon: Report to Command 05", "next": "exit", "action": "accept_quest"}, {"text": "I''ll decide later.", "next": "exit", "action": "exit"}]}, {"id": "exit", "text": "The briefing ends; the field report stays open.", "options": []}]'::jsonb, 'dialog_quests.json', 226)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_001', 'fq_arc_001', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Welcome to the Arcanum Seekers, Field Researcher. I''m High Seeker Elara Voss. The Concordium calls us reckless and the Iron Hegemony calls us dangerous — we call ourselves the only people on Xylos who are asking the right questions instead of just fortifying the answers they already have. Your first field assignment is on the Crystal Slope. The Wild Mushrooms there absorb raw aethel directly from a Shard fragment impact site. Their tissue contains energy signatures that predate the Great Severance. We need those signatures.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Aethelgardians who built the Aethel Siphon understood aethel energy at a fundamental level that we have been reconstructing from ruins for two centuries. The Crystal Slope sits on a direct Shard fragment impact point — one of the scatter sites where the original Shard dispersed when it shattered in the Great Severance. The Wild Mushrooms that have grown over this site are not random organisms, Subject. They are biological data storage: living tissue that has absorbed and encoded pre-Severance aethel signatures over three hundred years of contact. Those signatures are our most direct access to what the Aethelgardians knew before the Siphon overloaded and destroyed everything. The fact that obtaining them requires combat is a methodology compromise, not a philosophical one.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: First Watch 01. In Crystal Slope: Defeat 3 SHARDLING. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 227)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_002', 'fq_arc_002', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "The Crystal Sproutlings on this slope are not simply obstacles, Field Researcher. I believe they are conscious. Primitively, at the level of a single persistent idea perhaps, but the energy signature data from our previous collection suggests a form of biological coherence that standard Xylos fauna don''t exhibit. The Concordium classified this research as ''ethically complex'' and buried it in their restricted archive. The Arcanum opened it anyway.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Crystal Sproutlings grow from Shard fragment deposits — they are, technically, living extensions of the same material that shattered in the Great Severance. The Concordium wants them cleared as threats. The Children of the Shard would want them protected as sacred relics. We want their consciousness-signature data, because if these organisms carry biological memory encoded by the Shard''s fracture pattern, that memory could tell us things about the Aethelgardians'' original intent for the Siphon that no written archive has preserved. The Concordium''s ethical classification is not a philosophical objection — it''s administrative anxiety. There is a difference.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Broken Signal 01. In Crystal Slope: Defeat 3 SHARDLING. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 228)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_003', 'fq_arc_003', 'npc_arcanum_archivist', 'greeting', '[{"id": "greeting", "text": "I''m Archivist Sylas. I maintain what the Arcanum calls the living archive — our collection of specimens, artifacts, and data constituting institutional knowledge no single researcher can hold alone. High Seeker Voss has sent you to me because I have a hypothesis that requires specimens I cannot collect myself. The Shardlings on this slope are not random creatures. I believe each one contains a fractional encoded memory of the original Aethel Shard — a fractal pattern of the whole, distributed across biological hosts.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The fractal hypothesis began with the Sproutling consciousness data. If Sproutlings carry primitive coherent awareness derived from Shard contact, and Shardlings are organisms that developed from direct fragment integration, then the Shardling population may collectively encode the Shard''s pre-fracture information state. The fracture pattern itself — the way the Shard shattered, where each fragment landed — may not have been random. The Aethelgardians may have engineered the Shard to fracture in a recoverable pattern, a fail-safe in the event the Siphon failed. If I am right, we could theoretically reconstruct the Shard''s original data state from biological specimens. The Concordium has never considered this possibility because they stopped asking questions the moment the Cradle started working again.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Ashes on the Route 01. In Crystal Slope: Defeat 3 SHARDLING. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 229)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_004', 'fq_arc_004', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "An Aethelgardian text recovered from the Resonance Caverns — one of the Arcanum''s most prized possessions, classified by the Concordium and recovered during the chaos of the Schism — describes Crystal Wisps as ''light-formed messengers, carrying the speech of those who built the Siphon.'' The Concordium wants them dead. The Arcanum wants their energy signatures mapped. These are different objectives, Field Researcher, and the difference matters enormously.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Aethelgardian text provides a partial translation framework for Wisp energy patterns: they are not random light emissions but structured data bursts — the same communication protocol the Aethelgardians used to transmit technical information across the Siphon''s operational network. Every Wisp that flickers out is a word from before the Severance, lost forever. Our capture equipment can preserve the energy signature at the moment of dispersal — essentially recording the Wisp''s final transmission. We have been building a corpus of these recordings for six years. When we have enough, we may be able to reconstruct complete Aethelgardian technical instructions from the accumulated data. The Concordium has never attempted this because they are not interested in what the Aethelgardians were saying. Only in what they built.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Quiet Perimeter 01. In Crystal Slope: Defeat 3 CRYSTAL_WISP. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 230)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_005', 'fq_arc_005', 'npc_arcanum_class_trainer', 'greeting', '[{"id": "greeting", "text": "I am Archsage Myr. The Observatory Spire was built by the Arcanum to watch the stars and read the aethel currents that flow between them — and because the person who designed it believed that the Aethelgardians were communicating something in the pattern of the Shard fragment scatter, and that pattern would only be visible from sufficient altitude. I have reviewed your field reports. High Seeker Voss and Archivist Sylas both recommend you. In the Arcanum, knowledge specialization is not a promotion. It is a philosophical declaration.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The Arcanum recognizes three lines of inquiry — not classes, not tactical roles, but commitments about what questions you will spend your life pursuing. The Resonance Seeker listens: studying frequencies, emissions, and the hidden communications embedded in aethel phenomena, following the Wisp translation project''s methodology. The Void Architect constructs: building frameworks for understanding void energy and its relationship to the Shard, working toward practical applications the Concordium hasn''t imagined. The Crystal Sage synthesizes: combining biological specimen data with Aethelgardian technical records to reconstruct lost knowledge from fragments. The wrong answer will not be punished — the Arcanum does not punish intellectual honesty. But it will shape everything you investigate from this day forward.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: A Debt Repaid 01. In Crystal Slope: Defeat 3 GLASS_CRAWLER. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 231)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_006', 'fq_arc_006', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "The Fractured Glass Valley was a functioning Aethelgardian research station before the Severance shattered it — and the terrain along with it. The valley''s glass formations are the remnants of research structures that were conducting experiments the Concordium still cannot categorize from the fragments we''ve recovered. I''ve been trying to get a team into this valley for years. The Concordium kept classifying it restricted. Post-Schism, in the fracture of competing jurisdictions, the Arcanum moves where others hesitate. Get in before anyone else does.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The restriction was bureaucratic cowardice. The Concordium''s position was that the valley''s ''unstable terrain'' made access ''inadvisable.'' The actual reason, which their internal correspondence reveals to anyone willing to access the Arcanum''s recovered archive fragments, is that the pre-Severance research conducted here involved aethel applications that the Concordium''s post-Schism engineering division cannot replicate and doesn''t want the general population to know about. Data slates buried in the crystalline formations contain material science experiment records that our current understanding cannot fully categorize. That is precisely why we are here. The Concordium restricts what it cannot understand. The Arcanum investigates it.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: The Missing Patrol 01. In Crystal Slope: Defeat 3 GLASS_CRAWLER. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 232)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_007', 'fq_arc_007', 'npc_arcanum_archivist', 'greeting', '[{"id": "greeting", "text": "I''m Archivist Sylas. I have been studying the Glass Crawlers'' locomotion pattern in this valley for three months and I believe I have found something extraordinary. Their movement technique — the way they distribute weight across the razor-glass substrate without cutting themselves — follows a stress-distribution algorithm that precisely matches a partial specification recovered from the research station''s structural engineering archives. They didn''t evolve this solution. They inherited it.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The implication is significant. The Aethelgardian research station was conducting biological integration experiments — attempting to encode engineering solutions into living organisms'' behavioral genetics. If the Glass Crawlers'' locomotion is a survival of that research, it means the station''s biological experiments were successful enough that the encoded behaviors persisted through three hundred years of independent evolution. The Crawlers are, in a meaningful sense, living Aethelgardian documentation — organisms that remember engineering solutions their creators recorded in their genetics. That movement data could reshape Arcanum field equipment design and tell us what else the Aethelgardians may have successfully encoded in Xylos''s native fauna.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Measure of Resolve 01. In Crystal Slope: Defeat 3 ARCANE_SHARDLING. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 233)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_008', 'fq_arc_008', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "A Giant Alpha Rat has claimed the valley''s sealed archive chamber as its nest. This is the chamber our scouts confirmed still contains pre-Severance data cylinders intact after three hundred years. The chamber''s aethel-key sealing mechanism kept the biological contamination of the Severance out. It did not keep out a rat that found the ventilation shaft. The Concordium had this chamber on their survey maps for decades and left it sealed. The Arcanum broke through last season. A rat will not reclaim what human curiosity has finally unlocked.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The data cylinders in that chamber were sealed by Aethelgardian archivists who understood the Siphon was failing. They preserved what they could before the Great Severance destroyed everything else. Three hundred years of perfect environmental sealing — the aethel-key technology creates an atmosphere-isolated container that resists biological and energetic contamination simultaneously. The Alpha Rat''s colony is using the document storage containers as nesting material. Every week the Alpha remains in that chamber, more cylinders are compromised. The Concordium''s decades of neglect made this possible. The Arcanum cannot afford the same mistake.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: A Narrow Passage 01. In Crystal Slope: Defeat 3 ARCANE_SHARDLING. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 234)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_009', 'fq_arc_009', 'npc_researcher_vin', 'greeting', '[{"id": "greeting", "text": "I''m Researcher Vin. My field specialization is energy signature analysis — I measure what things emit and attempt to understand what those emissions mean about the emitter''s underlying nature. The Glass Wisps in this valley have presented me with what I can only describe as a professional emergency: their energy signatures are so complex that my standard field equipment cannot parse them. High Seeker Voss finds this exciting. I find it a calibration problem I need to solve.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "The standard Crystal Wisp emits energy in patterns consistent with simple harmonic resonance — first-order transmissions, in the Aethelgardian terminology, basically a single sustained note. The Glass Wisps are emitting recursive harmonic structures: patterns that reference themselves, that contain within them scaled-down versions of the whole emission signature. This is what the Arcanum''s theoretical models predict for aethel entities that have spent generations in high-compression radiation environments — the Fractured Glass Valley''s crystalline substrate concentrates ambient aethel to levels three to four times higher than the Crystal Slope. These Wisps are not just older Crystal Wisps. They are something qualitatively different, and my equipment was designed for the simpler version.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Unclaimed Ground 01. In Crystal Slope: Defeat 3 CRYSTAL_SKITTER. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 235)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_010', 'fq_arc_010', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "The Crystal Rams in the valley''s deepest ravine have horns I have been studying for fourteen months. Not the keratin structure itself — the electromagnetic pattern they emit. The Rams'' horns grow by absorbing the deep aethel currents flowing through the valley''s crystalline substrate, the same currents that once powered Aethelgardian technology. The resulting biological structure is, functionally, an aethel conduit grown over decades into a shape that mirrors the Siphon''s internal routing architecture. They solved in biology what the Aethelgardians solved in engineering.", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "I have a reconstruction project I have not shared with the Concordium and will not share with the Concordium. The project involves building a functional small-scale replica of the Siphon''s internal aethel routing system using biological components — specifically, the electromagnetic pattern of the Crystal Ram horn as a template for the routing geometry. If the Aethelgardians were encoding engineering solutions in Xylos''s native fauna, the Crystal Rams may be the most sophisticated example we''ve found. The horn''s pattern is not just similar to the Siphon''s routing architecture. It is structurally identical to specifications from pre-Severance construction documents that the Concordium classified before the Schism and that I recovered from their restricted archive through means I prefer not to detail.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Before the Next Dawn 01. In Fractured Glass Valley: Defeat 3 CRYSTAL_RAM. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 236)
on conflict (dialog_id) do update set quest_id=excluded.quest_id, npc_id=excluded.npc_id, start_node=excluded.start_node, nodes=excluded.nodes, source_file=excluded.source_file, sort_order=excluded.sort_order;
insert into public.dialogs (dialog_id, quest_id, npc_id, start_node, nodes, source_file, sort_order)
values ('dialog_fq_arc_011', 'fq_arc_011', 'npc_arcanum_scholar', 'greeting', '[{"id": "greeting", "text": "Scholar! The Observatory has been recording unusual patterns. The Resonance Caverns were discovered by an Arcanum expedition three years ago", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": ""}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Your previous encounters generated extraordinary data. The resonance patterns suggest a deeper structure — a language waiting to be decoded.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": ""}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Field Specimens: Witness at the Ridge 01. In Fractured Glass Valley: Defeat 4 CRYSTAL_RAM. Record what you observe after the encounter. A result without context is only another rumor.", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 237)
